select public.import_products($json$[{"sku":"PCPL-945","name":"Dague Predathor SALVIMAR","brand":"SALVIMAR","category_path":["plongee"],"description":"Dague PREDATOR SALVIMARNettoyer et écaillez vos prises avec la dague de chasse sous-marine PREDATHOR SALVIMAR compacte et anti-corrosion.Couteau très compact d’une longueur maximale de 16 cm avec étui pour une utilisation chasse ou apnée.Lame acier inox 420 à double fil. L’un lisse et l’autre dentelé.Longueur totale 16 cmLongueur de la lame 8 cmLongueur affutable 7 cmLame en acier inox 420 à double fil : un côté lisse et l’autre denteléSystème de fixation rapide adaptée au bras, avant bras, mollet ou ceintureNouveau manche ergonomique au design surprenant, disponible en coloris : vert, vert acide, orange et blancLivrée SANS sanglesATTENTION : aucune sangles livrées avec ce couteau.","price_cents":2499,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCPL-945/01-timthumb.php1.jpg"},{"sku":"PCPL-975","name":"SANDOWS CIRCULAIRE Ø 18 MM DESSAULT","brand":"DESSAULT","category_path":["plongee"],"description":"Le savoir-faire Dessault allié à la qualité des produits utilisés, procure à nos sandows un module d'élasticité bien supérieur aux autres types de latex naturels ou synthétiques.La production en fil continu préserve les chaînes moléculaires du latex.Associée à une maîtrise parfaite du séchage, cette technique permet d'atteindre exactement la nervosité et la longévité recherchée.Réputée efficace et robuste, la gomme Dessault a séduit de nombreux chasseurs à travers toutes les mers.Caractéristiques techniques : - Gomme noire diamètre 18 mm- Pure sève d'hévéa de Malaisie, 100% naturelle- Séchage lent et naturel- Vulcanisation continue- Testés individuellement- Fabrication française depuis 20 ans","price_cents":1299,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCPL-975/01-sandow-16_2_1.jpg"},{"sku":"PCSU-0000437","name":"COMBINAISON DE PLONGEE ET D'APNEE MONOPIECE FEMME ALIZE 7 MM AVEC CAGOULE | BEUCHAT","brand":"BEUCHAT","category_path":["plongee","chasse-sous-marine","combinaisons-de-chasse"],"description":"Achetez COMBINAISON DE PLONGEE ET D'APNEE MONOPIECE FEMME ALIZE 7 MM AVEC CAGOULE | BEUCHAT chez Cabesto : livraison express, paiement en 3 ou 4 fois sans frais et retour sous 30 j.","price_cents":17500,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCSU-0000437/01-alize-7-cag_2_1.jpg"},{"sku":"PCSU-0001070","name":"Bottilons de plongée CLASSIC NG 5 mm MARES","brand":"MARES","category_path":["plongee","longe-cote-marche-aquatique","equipement-pour-le-longe-cote"],"description":"Plongez et marchez avec les bottillons de plongée en néoprène CLASSIC NG 5 mm MARES, offrant un excellent maintien du pied, une protection thermique fiable et une semelle robuste pour des plongées confortables en toutes conditions.","price_cents":3499,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCSU-0001070/01-ngg_1.jpg"},{"sku":"PCSU-0001417","name":"Cagoule de plongée X-TREM Homme 6.5 mm BEUCHAT","brand":"BEUCHAT","category_path":["plongee","plongee-sous-marine","accessoires-neoprene-plongee"],"description":"Protégez votre tête du froid et équipez votre semi étanche X-TREM avec la cagoule X-TREM pour homme, épaisseur 6.5 mm, souple et facile à mettre et à enlever.","price_cents":4799,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCSU-0001417/01-semi-dry-x-trem-cagoule-homme_1_.jpg"},{"sku":"PCSU-0002381","name":"Combinaison de plongée étanche Femme EVERDRY 4MM SCUBAPRO","brand":"SCUBAPRO","category_path":["plongee","plongee-sous-marine","combinaisons-de-plongee"],"description":"Combinaison de plongée étanche Femme EVERDRY 4.0 SCUBAPROPlongez au sec et donc au chaud avec la combinaison de plongée sous-marine étanche pour femme EVERDRY 4.0, le vêtement sec en néoprène compressé souple pour femme simple à utiliser et confortable pour vos plongées en eaux froides.la combinaison étanche EVERDRY 4.0 SCUBAPRO est un vêtement haut de gamme en néoprène comprimé offrant un look élégant féminin prés du corps.L'utilisation d'un EVERDRY 4.0 est comparable au confort d'usage et à la souplesse d’une combinaison humide classique mais avec les propriétés thermiques et l’étanchéité d’un vêtement étanche.L'EVERDY 4.0 femme SCUBAPRO est équipée de nouveaux panneaux aux épaules ainsi qu'aux genoux, d’une doublure interne en plush bleu \"diamond span\" , de manchons de poignets en néoprène lisses et de bretelles internes bleues amovilbes.Le néoprène dense de 4 mm d'épaisseur résiste à la compression en profondeur et permet de porter la combinaison EVERDY 4.0 seule ou avec un sous-vêtement fin.Conçue pour un confort optimal et une utilisation prolongée, la Everdry 4 est parfaitement ajustée, offre une excellente liberté de mouvement et, surtout, garde la chaleur corporelle à l’intérieur du vêtement tout en empêchant toute entrée d’eau froide.Néoprène haute densité 4 mm 50 % moins lourd et considérablement plus souple que le néoprène traditionnellement utilisé dans la fabrication de combinaisons étanches.Coutures à deux fils triplement collées et à points invisibles à l’extérieur, et enduites de polymère liquide à l’intérieur pour une étanchéité durable.Doublure en plush est confortable et assure une meilleure isolation thermique en eaux froides.Collerette lisse repliable en néoprène et ses manchons de poignets ultra-lisses sont confortables et assurent une excellente étanchéité.Ultra-résistante, sa fermeture à glissière étanche dorsale d’épaule à épaule BDM en métal est recouverte par un rabat en néoprène.Purges d’admission sur le côté et soupapes d’évacuation réglables Si-Tech, pour un contrôle parfait de la flottabilité et une meilleure stabilité en profondeur.Les panneaux présents aux épaules et aux genoux couvrent une large surface pour une résistance optimale contre l’abrasion.Ses chaussons en néoprène intégrés permettent de retourner complètement la combinaison pour le nettoyage et le séchage.Ses bretelles bleues assurent un meilleur ajustement ainsi qu’un bon maintien de la partie inférieure du vêtement entre chaque plongée.Ses sangles I-Safe assurent une bonne fixation de vos instruments aux poignets.Sur la cuisse droite, une poche cargo pratique munie d’un anneau en D, d’un cordon élastique et d’une fermeture à glissière permet le transport d’accessoires en toute sécurité.Cagoule anatomique, sac de transport, bretelles, flexible basse pression, kit de réparation, lubrifiant pour fermeture et notice d’utilisation inclus.Le produit en vidéoNéoprène 4 mm compressé souple et chaudLe néoprène comprimé permet de conserver une flottabilité constante lors de vos plongées, contrairement à un néoprène classique en 5 ou 7 mm qui se comprime avec l'augmentation de la pression ambiante. En clair, la combinaison EVERDRY conserve ses 4 mm d'épaisseur en surface comme au fond pour une gestion simplifiée de votre flottabilité.Cagoule séparée épaisseur 6/4 mmCagoule anatomique confortable et chaude, doublure plush \"diamond span\" interne.Bretelle de maintien intégré démontableSes bretelles bleues assurent un meilleur ajustement ainsi qu’un bon maintien de la partie inférieure du vêtement entre chaque plongée.Sac de transport et de stockage plat, pouvant servir de tapis de solSac de transport, bretelles, flexible basse pression, kit de réparation, lubrifiant pour fermeture et notice d’utilisation inclus.Caractéristiques Combinaison de plongée étanche Femme EVERDRY 4.0 SCUBAPROCombinaison étanche haut de gamme en néoprène compriméEpaisseur 4 mm avec chaussons souplesCombinaison profilé près du corps coupe femme pour une trainée hydrodynamique faibleCompatible avec le port d'un sous-vêtement finSouplesse d'utilisation et liberté de mouvement optimiséInformations techniques :Type de combinaison Combinaison étancheMatériau Néoprène compresséEpaisseur 4 mmPoids 3.7 kg (taille M)Fermeture Métallique étanche Poche 1 latérale de cuisseManchons étanches Néoprène poignets et couCagoule séparée OuiSac de transport OuiGarantie 2 ans, hors manchons néoprèneContenu du colis1 x Combinaison étanche femme EVERDRY 4 mm SCUBAPRO1 x Sac de transport et de stockage1 x Cagoule séparée1 x Flexible basse pression long type direct system1 x Kit d'entretien avec rustine, colle, pochette de talc et parafinne pour fermeture métal1 x Notice d'utilisation","price_cents":99900,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCSU-0002381/01-sp_60863xx0_everdry_4mm_01.jpg"},{"sku":"PCSU-0002385","name":"Combinaison de plongée étanche Homme EVERDRY 4 mm SCUBAPRO","brand":"SCUBAPRO","category_path":["plongee","plongee-sous-marine","combinaisons-de-plongee"],"description":"Plongez au sec et donc au chaud avec la combinaison de plongée sous-marine étanche EVERDRY 4.0, le vêtement sec en néoprène compressé souple pour homme simple à utiliser et confortable pour vos plongées en eaux froides.","price_cents":99900,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCSU-0002385/01-ever.jpg"},{"sku":"PCSU-0002468","name":"COMBINAISON DE PLONGEE FACILE 8 MM HOMME | CRESSI SUB","brand":"CRESSI","category_path":["plongee","plongee-sous-marine","combinaisons-de-plongee"],"description":"Achetez COMBINAISON DE PLONGEE FACILE 8 MM HOMME | CRESSI SUB chez Cabesto : livraison express, paiement en 3 ou 4 fois sans frais et retour sous 30 j.","price_cents":37700,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCSU-0002468/01-575_cressi-wetusit-facile-man_z_1.jpg"},{"sku":"PCSU-0002544","name":"Lampe de plongée sous-marine TL2900 P BIGBLUE","brand":"BIGBLUE DIVE LIGHTS","category_path":["plongee","plongee-sous-marine","eclairage-photo-video"],"description":"Éclairez au loin sous l'eau et profitez d’un éclairage sous-marin puissant et précis avec le faisceau étroit de la lampe étanche sous-marine TL2900P BIGBLUE, pour une visibilité améliorée pendant vos plongées d'exploration ou techniques.","price_cents":34500,"compare_at_price_cents":null,"stock":12,"co